function Error(error) {

  var payload = {
    message: error.message,
    fileName: error.filename,
    lineNumber: error.lineno,
    columnNumber: error.colno,
  };
  Send_Error(payload);

  // true: for dont display error on console
  // this is not work for this function because this function is a listener.
  // if you want to make error slient for console; you have to type return true in window.onError method.
  return true;
}
var openTime = undefined;

function StatisticOnLoad() {

    console.log("st:onload");

    // this will use for update statistic data at the server with OnUnLoad Data
    openTime = new Date().getTime();

    var payload = {
        type: "open",
        openTime: openTime + "",
        referrer: document.referrer,
        startTime: new Date().toLocaleString("tr-TR"),
    };
    Send_Statistic(payload);

    console.log("statistic send");
}

function StatisticOnUnLoad() {

    var payload = {
        type: "close",
        openTime: openTime,
        endTime: new Date().toLocaleString("tr-TR"),
    };
    Send_Statistic(payload);
}

function UserExperienceOnLoad() {
    console.log("ux:onload");

    var steruxClick = "steruxClick";

    // add click listener to body
    document.getElementsByTagName("BODY")[0].addEventListener('click', function (e) {
        for (var i = 0; i < e.path.length - 2; i++) {
            var element = e.path[i];
            if (element.getAttribute(steruxClick) != undefined) {

                var payload = {
                    elementName: element.getAttribute(steruxClick),
                    eventType: "Click",
                };
                Send_UserExperence(payload);
            }
        }
    }, false);

    // for first run:
    Scroll();
}

function UserExperienceOnUnLoad() {

}

var steruxView="steruxView";

function Scroll() {

    var elements = document.querySelectorAll('['+steruxView+']');

    for (var i = 0; i < elements.length; i++) {
        var element = elements[i];

        if (element.getAttribute("viewControlViewed") == null) {
            if (isElementOnViewPort(element)) {
                element.setAttribute("viewControlViewed", true);

                var payload = {
                    elementName: element.getAttribute(steruxView),
                    eventType: "View",
                };
                Send_UserExperence(payload);
            }
        }
    }

}



// Functions:

function isElementOnViewPort(el) {
    try {
        var rect = el.getBoundingClientRect();
        // DOMRect { x: 8, y: 8, width: 100, height: 100, top: 8, right: 108, bottom: 108, left: 8 }
        var windowHeight = (window.innerHeight || document.documentElement.clientHeight);
        var windowWidth = (window.innerWidth || document.documentElement.clientWidth);

        // http://stackoverflow.com/questions/325933/determine-whether-two-date-ranges-overlap
        var vertInView = (rect.top <= windowHeight) && ((rect.top + rect.height) >= 0);
        var horInView = (rect.left <= windowWidth) && ((rect.left + rect.width) >= 0);

        return (vertInView && horInView);

    } catch (error) {
        return false;
    }
}
var SteruxOptions;
var userId;

function STERUXOnLoad() {

    // if there is not steruxClientId, send user information and set it with response
    var steruxClientId = getSteruxClientIdCookie();
    var steruxClientLoginStatus = getSteruxLoginStatusCookie();
    var isUserLogined = (getLoginedUserCookie() == undefined) ? false : true;

    if (steruxClientId == undefined) {
        // client opening the page first time, it have to send user information for getting steruxClientID
        var payload = {
            type:"create",
            steruxClientId:undefined,
            user: GetUserInformations(),
            dateTime: new Date().toLocaleString("tr-TR"),
        }
        // user login status
        payload.user.isLogined = isUserLogined;

        Send_UserInformation(payload);

    } else if (steruxClientId != undefined && steruxClientLoginStatus == "false" && isUserLogined == true) {
        // if there is steruxClientID, and user logined but steruxClientLogin status is false
        // it have to informed the server for update current user as logined
        var payload = {
            type:"update",
            steruxClientId:steruxClientId,
            dateTime: new Date().toLocaleString("tr-TR"),
            user: {},
        }
        // user login status
        payload.user.isLogined = isUserLogined;

        Send_UserInformation(payload);
    }else (steruxClientId != undefined && steruxClientLoginStatus == "false" && isUserLogined == true)
}

function SteruxInit(option) {
    SteruxOptions = option;

    window.addEventListener('load', STERUXOnLoad);

    if (SteruxOptions.modules.statistic) {
        window.addEventListener('load', StatisticOnLoad);
        window.addEventListener('unload', StatisticOnUnLoad);
    }

    if (SteruxOptions.modules.ux) {
        window.addEventListener('load', UserExperienceOnLoad);
        window.addEventListener('unload', UserExperienceOnUnLoad);

        window.addEventListener('scroll', Scroll);
    }

    if (SteruxOptions.modules.error) {
        window.addEventListener('load', ErrorOnLoad);
        window.addEventListener('unload', ErrorOnUnLoad);
        window.addEventListener('error', Error);
    }

}

